H,W=23,22
g=[[0]*W for _ in range(H)]
def paint(r,c,color): g[r][c]=color
# 5 frame
for c in range(2,10): paint(2,c,5); paint(6,c,5)
for r in range(3,6): paint(r,2,5); paint(r,9,5)
# 8 frame
for c in range(12,22): paint(1,c,8); paint(6,c,8)
for r in range(2,6): paint(r,12,8); paint(r,21,8)
# 1 frame
for c in range(11,19): paint(8,c,1); paint(12,c,1)
for r in range(9,12): paint(r,11,1); paint(r,18,1)
# 7 source frame
for c in range(1,9): paint(12,c,7); paint(16,c,7)
for r in range(13,16): paint(r,1,7); paint(r,8,7)
# source interior 3x6 mask read from test
mask=[[0,7,7,0,0,7],[7,7,0,7,7,7],[0,7,7,7,0,0]]
for dr in range(3):
 for dc in range(6):
  if mask[dr][dc]: paint(13+dr,2+dc,7)
# 6 frame
for c in range(15,21): paint(14,c,6); paint(19,c,6)
for r in range(15,19): paint(r,15,6); paint(r,20,6)
# 3 frame
for c in range(4,13): paint(18,c,3); paint(21,c,3)
for r in range(19,21): paint(r,4,3); paint(r,12,3)
# stamp source mask into same-size hollow frames: 5 frame inner 3x6, and 1 frame inner 3x6
out=[row[:] for row in g]
for r0,c0,col in [(3,3,5),(9,12,1)]:
 for dr in range(3):
  for dc in range(6): out[r0+dr][c0+dc]=col if mask[dr][dc] else 0
assert len(out)==23 and all(len(row)==22 for row in out)
print('INPUT_CHECK rows',len(g),'widths',sorted(set(map(len,g))))
print('output')
import json
print(json.dumps(out,separators=(',',':')))
print('changes',[(r,c,out[r][c]) for r in range(H) for c in range(W) if out[r][c]!=g[r][c]])

